DISPLAY_SOURCE = "# F3: same percentage bars, now with consistent source names.\nfig,axes=plt.subplots(2,1,figsize=(6.25,4.25));fig.subplots_adjust(left=.13,right=.865,bottom=.19,top=.91,hspace=1.4)\nfor k,(ax,grp,labs,cs,title) in enumerate(zip(axes,['R','H'],[['Same direction','Neutral','Reversed'],['Smaller','Within band','Larger']],[[blue,gray,red],[blue,gray,gold]],['Total-price direction among qualifying electricity changes','Total-minus-electricity amount where directions agree'])):\n    if k==0:data=np.array([[int((d[d.R].total_category==x).sum()) for x in ['retained','neutralized','reversed']] for d in [b,s]])\n    else:data=np.array([[int((d[d.H].signed_category==x).sum()) for x in ['negative','near','positive']] for d in [b,s]])\n    expected=[[[7479,27,25],[1377,1678,1866]],[[1157,4773,1549],[1301,39,37]]][k]\n    if k==1 and not np.array_equal(data,expected):\n        data=np.array([[int((d.loc[d.H,'D30']<-.9).sum()),int((d.loc[d.H,'D30'].abs()<=.9).sum()),int((d.loc[d.H,'D30']>.9).sum())] for d in [b,s]])\n    assert np.array_equal(data,expected),(k,data)\n    den=data.sum(axis=1);left=np.zeros(2);y=[1,0]\n    for vals,lab,col in zip(data.T,labs,cs):\n        widths=100*vals/den;ax.barh(y,widths,left=left,color=col,height=.54,label=lab)\n        for j,w in enumerate(widths):\n            if w>=7:ax.text(left[j]+w/2,y[j],f'{vals[j]:,}\\n({w:.1f}%)',ha='center',va='center',fontsize=8,color='white' if col in [blue,red] else '#18272e')\n        left+=widths\n    for j in [0,1]:ax.text(101,y[j],f'n={den[j]:,}',va='center',fontsize=8)\n    ax.set(yticks=y,yticklabels=['Beijing','Shenzhen'],xlim=(0,100),xlabel=f'Share of {grp} (%)');ax.grid(axis='x',alpha=.13)\n    ax.set_title(f'({chr(97+k)}) '+title,loc='left',pad=7);ax.tick_params(axis='y',length=0);ax.legend(ncol=3,loc='upper center',bbox_to_anchor=(.52,-.48),frameon=False,handlelength=1.2)\nsave(fig,3);rec(3,[popfile],'Original six categories and denominators, independently matched to B1 Table 4')\n# F4: regenerate only its two intended empirical CDFs; the B1 clipped form contained unrelated screening graphics.\nfig,axes=plt.subplots(2,1,figsize=(6.25,5.7));fig.subplots_adjust(left=.135,right=.975,bottom=.105,top=.943,hspace=.41)\nfor i,ax in enumerate(axes):\n    for d,name,c in [(b,'Beijing',blue),(s,'Shenzhen',red)]:\n        for pop,ls in [('A','-'),('R','--'),('H',':')]:\n            orig=d.loc[d[pop],'D30'].to_numpy();xs=np.sort(np.abs(orig) if i else orig);assert np.isfinite(xs).all()\n            ax.step(xs,np.arange(1,len(xs)+1)/len(xs),where='post',lw=1.1,ls=ls,color=c,label=name+' '+pop)\n    ax.set_xscale('symlog',linthresh=.1)\n    ax.set(ylim=(-.01,1.025),xlabel=(r'$|D_{30}|$' if i else r'$D_{30}$')+' (RMB per reference 30 kWh)',ylabel='Cumulative share');ax.grid(axis='y',alpha=.15)\n    ax.set_title(('(a) Signed discrepancy','(b) Absolute discrepancy')[i],loc='left',pad=6)\n    if i:ax.axvline(.9,ls='--',lw=.85,c=gray);ax.set_xlim(left=0);ax.text(.03,.10,'Dashed reference: RMB 0.90',transform=ax.transAxes,fontsize=8)\n    else:ax.axvline(0,lw=.65,c=gray);ax.legend(frameon=False,loc='lower right',ncol=2,fontsize=8,handlelength=2.2)\nsave(fig,4);refcode=REL/'src/distribution/analyze_input_application.py';check_tag(refcode);rec(4,[popfile,refcode],'Exact step ECDF across full range, linthresh 0.1; standalone signed and absolute panels')\n"
